import pytest
from candidate import truncate_number

class TestTruncateNumber:

    def test_truncate_number_with_decimal(self):
        assert truncate_number(3.5) == 0.5

    def test_truncate_number_with_integer_part(self):
        assert truncate_number(3) == 0.0

    def test_truncate_number_with_zero(self):
        assert truncate_number(0) == 0.0

    def test_truncate_number_with_large_number(self):
        assert truncate_number(12345.6789) == 0.6789

    def test_truncate_number_with_large_number_no_decimal(self):
        assert truncate_number(12345) == 0.0

    def test_truncate_number_with_negative_number(self):
        with pytest.raises(TypeError):
            truncate_number(-3.14)

    def test_truncate_number_with_large_negative_number(self):
        assert truncate_number(-123.456) == 0.456

    def test_truncate_number_with_large_negative_number_no_decimal(self):
        assert truncate_number(-123) == 0.0

    def test_truncate_number_with_extremely_large_number(self):
        assert truncate_number(1e100) == 0.0

    def test_truncate_number_with_extremely_large_number_with_decimal(self):
        assert truncate_number(1e100 + 0.123) == 0.123

    def test_truncate_number_with_small_nonzero_decimal(self):
        assert truncate_number(0.001) == 0.001

    def test_truncate_number_with_large_decimal(self):
        assert truncate_number(1000.99999) == 0.99999

    def test_truncate_number_with_large_decimal_no_integer_part(self):
        assert truncate_number(1000.123456) == 0.123456

    def test_truncate_number_with_zero_decimal(self):
        assert truncate_number(0.0) == 0.0

    def test_truncate_number_with_large_float(self):
        assert truncate_number(1e-100) == 0.0

    def test_truncate_number_with_large_float_no_decimal(self):
        assert truncate_number(1e-100 + 0.123) == 0.123
